class Student {
    String name;
    double marks;

    void checkResult() {
        if (marks >= 50.0) {
            System.out.println(name + " Result: PASSED");
        } else {
            System.out.println(name + " Result: NEEDS IMPROVEMENT");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Student s = new Student();
        s.name = "Kavya";
        s.marks = 62.0;
        s.checkResult();
    }
}

